# Reviewed under AGENTS.md
from __future__ import annotations

from collections import OrderedDict
from typing import Generic, TypeVar

K = TypeVar('K')
V = TypeVar('V')


class LRUCache(Generic[K, V]):
    """A fixed-capacity cache that evicts the least recently used key.

    Both ``get`` and ``put`` count as a use: the touched key becomes the most
    recently used one, so it is the last candidate for eviction.
    """

    def __init__(self, capacity: int) -> None:
        if capacity < 1:
            raise ValueError(f'capacity must be at least 1, got {capacity}')
        self._capacity = capacity
        # Ordered from least (first) to most (last) recently used.
        self._data: OrderedDict[K, V] = OrderedDict()

    def get(self, key: K) -> V | None:
        """Return the value for ``key``, or ``None`` if absent; counts as a use."""
        if key not in self._data:
            return None
        self._data.move_to_end(key)
        return self._data[key]

    def put(self, key: K, value: V) -> None:
        """Insert or update ``key``, evicting the least recently used key if over capacity."""
        if key in self._data:
            self._data.move_to_end(key)
        elif len(self._data) == self._capacity:
            self._data.popitem(last=False)
        self._data[key] = value

    def __len__(self) -> int:
        return len(self._data)
